class Solution:
    def combinationSum3(self, k: int, n: int) -> List[List[int]]:
        res, path = [], []

        def dfs(start: int, remaining: int) -> None:
            if len(path) == k:
                if remaining == 0:
                    res.append(path[:])
                return
            for d in range(start, 10):           # digits strictly increase: no repeats, no permutations
                if d > remaining:
                    break
                path.append(d)
                dfs(d + 1, remaining - d)
                path.pop()

        dfs(1, n)
        return res
